/* ============================= WORDLE WORD LISTS =============================
   Relocated verbatim from the original single-file Puzzlr.jsx. Two flat strings
   of concatenated 5-letter words, sliced back apart at load: VALID (~14,855
   accepted guesses) and ANSWERS (2,500 common words used as puzzles). Every
   answer is also present in VALID, so there are no unwinnable puzzles. */
const VALID = "";
const ANSWERS = "";

const validSet = new Set();
for (let i = 0; i < VALID.length; i += 5) validSet.add(VALID.slice(i, i + 5));
const answerList = [];
for (let i = 0; i < ANSWERS.length; i += 5) answerList.push(ANSWERS.slice(i, i + 5));

export { validSet, answerList };